from collections import deque

def connected_components(grid, connectivity=4):
    """Find connected components in the grid."""
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    components = []

    def flood_fill(r, c, value):
        comp = [(r, c)]
        visited[r][c] = True
        stack = [(r, c)]

        while stack:
            cr, cc = stack.pop()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc] and grid[nr][nc] == value:
                        visited[nr][nc] = True
                        comp.append((nr, nc))
                        stack.append((nr, nc))
        return comp

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                comp = flood_fill(r, c, grid[r][c])
                if comp:
                    components.append(comp)

    return components

