def get_8conn_component_groups(grid):
    """Find maximal 8-conn regions (ignoring colors during grouping)."""
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]

    groups = []  # List of [(r,c)] for each group

    group_id = 0
    for r in range(h):
        for c in range(w):
            if not visited[r][c]:
                group = []
                stack = [(r, c)]
                visited[r][c] = True
